// Spec: 0053-sql-typed FR-008
/**
 * The typed tables of the issues model, generated by IFC Data from the model. Do not edit: change the model and run `bun tools/typed.ts --write`.
 *
 * The issues a repository keeps as code, as records
 *
 * @module
 */
import { defineTable, type Timestamp } from "@intellectual-frontiers/data/sql/typed";

/** One known weakness of a library or a module, as the code of the repository says it */
export interface IssueRow {
  /** What identifies the issue: its scope and number */
  readonly issueId: string;
  /** The library or module it is of, by its path */
  readonly scope: string;
  /** Its number within the scope */
  readonly number: number;
  /** Its name in words joined by hyphens */
  readonly slug: string;
  /** What it is, in a line */
  readonly title: string;
  /** What is wrong and why it matters */
  readonly summary: string;
  /** How bad it is */
  readonly severity: "critical" | "high" | "medium" | "low";
  /** When it is to be done */
  readonly priority: "p_1" | "p_2" | "p_3";
  /** How much work the fix is */
  readonly size: "xs" | "s" | "m" | "l" | "xl";
  /** Where it is */
  readonly statusKind: "open" | "in_progress" | "fixed" | "wont_fix" | "not_a_defect" | "duplicate" | "deferred";
  /** Why, for a status that needs a reason */
  readonly statusReason: string | null;
  /** What shows it is done, for one that is fixed */
  readonly statusProof: string | null;
  /** The number of the issue it duplicates */
  readonly duplicateOf: number | null;
  /** Whether it is about every engine; where not, the engines are listed */
  readonly appliesToAll: boolean;
  /** The day it was raised */
  readonly raised: string;
  /** A hash of what the code says of it, so that a change is seen */
  readonly contentHash: string;
  /** Whether the code still has it */
  readonly presence: "present" | "withdrawn";
  /** When a synchronisation last wrote it */
  readonly syncedAt: Timestamp;
}

/** What an insert into issue takes: what the database fills may be left out. */
export interface IssueInsert {
  readonly issueId: string;
  readonly scope: string;
  readonly number: number;
  readonly slug: string;
  readonly title: string;
  readonly summary: string;
  readonly severity: "critical" | "high" | "medium" | "low";
  readonly priority: "p_1" | "p_2" | "p_3";
  readonly size: "xs" | "s" | "m" | "l" | "xl";
  readonly statusKind: "open" | "in_progress" | "fixed" | "wont_fix" | "not_a_defect" | "duplicate" | "deferred";
  readonly statusReason?: string | null;
  readonly statusProof?: string | null;
  readonly duplicateOf?: number | null;
  readonly appliesToAll: boolean;
  readonly raised: string;
  readonly contentHash: string;
  readonly presence: "present" | "withdrawn";
  readonly syncedAt: Timestamp;
}

/** The key of a row of issue. */
export type IssueKey = { readonly issueId: string };

/** One known weakness of a library or a module, as the code of the repository says it */
export const issue = defineTable<IssueRow, IssueInsert, "issue">({
  alias: "issue",
  name: "issue",
  columns: {
    issueId: "issue_id",
    scope: "scope",
    number: "number",
    slug: "slug",
    title: "title",
    summary: "summary",
    severity: "severity",
    priority: "priority",
    size: "size",
    statusKind: "status_kind",
    statusReason: "status_reason",
    statusProof: "status_proof",
    duplicateOf: "duplicate_of",
    appliesToAll: "applies_to_all",
    raised: "raised",
    contentHash: "content_hash",
    presence: "presence",
    syncedAt: "synced_at",
  },
  primaryKey: ["issueId"],
});

